jest.mock('../../../../../functions/fetch', () => ({
  __esModule: true,
  default: jest.fn(),
}));

import { h } from '@stencil/core';
import { newSpecPage } from '@stencil/core/testing';
import apiFetch from '../../../../../functions/fetch';
import { ScFulfillments } from '../sc-fulfillments';

const apiFetchMock = apiFetch as unknown as jest.Mock;

const flushFetches = () => new Promise(resolve => setTimeout(resolve, 0));

const shippableOrder = (status = 'paid', shipping_enabled = true) => ({
  id: 'order-id',
  status,
  checkout: {
    line_items: {
      data: [{ id: 'line-item-id', price: { product: { id: 'product-id', shipping_enabled } } }],
    },
  },
});

const mockFetch = ({ fulfillments = [], order = shippableOrder() } = {}) => {
  apiFetchMock.mockImplementation(({ path }) => {
    if (path.includes('surecart/v1/fulfillments')) return Promise.resolve(fulfillments);
    if (path.includes('surecart/v1/orders/')) return Promise.resolve(order);
    return Promise.reject(new Error(`Unexpected path: ${path}`));
  });
};

const renderPage = async (template = () => <sc-fulfillments orderId="order-id"></sc-fulfillments>) => {
  const page = await newSpecPage({
    components: [ScFulfillments],
    template,
  });
  await flushFetches();
  await page.waitForChanges();
  return page;
};

describe('sc-fulfillments', () => {
  beforeEach(() => {
    apiFetchMock.mockReset();
  });

  it('renders the order received notice when a paid shippable order has no fulfillments', async () => {
    mockFetch();
    const page = await renderPage();
    expect(page.root.style.display).not.toBe('none');
    const tag = page.root.shadowRoot.querySelector('sc-tag');
    expect(tag).not.toBeNull();
    expect(tag.textContent).toBe('Order Received');
    expect(page.root.shadowRoot.textContent).toContain('Your item will ship soon.');
    // The notice deliberately does not use shipment statuses — no shipment exists yet.
    expect(page.root.shadowRoot.querySelector('sc-fulfillment-shipping-status-badge')).toBeNull();
  });

  it('stays hidden for digital-only orders', async () => {
    mockFetch({ order: shippableOrder('paid', false) });
    const page = await renderPage();
    expect(page.root.style.display).toBe('none');
  });

  it('stays hidden for canceled orders', async () => {
    mockFetch({ order: shippableOrder('canceled') });
    const page = await renderPage();
    expect(page.root.style.display).toBe('none');
  });

  it('renders fulfillments normally and skips the order fetch when fulfillments exist', async () => {
    mockFetch({
      fulfillments: [{ id: 'fulfillment-id', number: '1001', shipment_status: 'shipped' }],
    });
    const page = await renderPage();
    expect(page.root.shadowRoot.querySelector('sc-fulfillment-shipping-status-badge')).not.toBeNull();
    expect(apiFetch).toHaveBeenCalledTimes(1);
  });

  it('renders returned fulfillments instead of the order received notice', async () => {
    mockFetch({
      fulfillments: [{ id: 'fulfillment-id', number: '1001', shipment_status: 'returned' }],
    });
    const page = await renderPage();
    expect(page.root.shadowRoot.querySelector('sc-fulfillment-shipping-status-badge')).not.toBeNull();
    expect(page.root.shadowRoot.textContent).not.toContain('Your item will ship soon.');
  });

  it('renders failed fulfillments instead of the order received notice', async () => {
    mockFetch({
      fulfillments: [{ id: 'fulfillment-id', number: '1001', shipment_status: 'failed' }],
    });
    const page = await renderPage();
    expect(page.root.shadowRoot.querySelector('sc-fulfillment-shipping-status-badge')).not.toBeNull();
    expect(page.root.shadowRoot.textContent).not.toContain('Your item will ship soon.');
  });

  it('requests returned and failed statuses from the API', async () => {
    mockFetch();
    await renderPage();
    const { path } = apiFetchMock.mock.calls[0][0];
    expect(path).toContain('returned');
    expect(path).toContain('failed');
  });

  it('stays hidden and skips the order fetch when showPreShipmentNotice is false', async () => {
    mockFetch();
    const page = await renderPage(() => <sc-fulfillments orderId="order-id" showPreShipmentNotice={false}></sc-fulfillments>);
    expect(page.root.style.display).toBe('none');
    expect(apiFetch).toHaveBeenCalledTimes(1);
  });

  it('stays hidden when the order fetch fails', async () => {
    apiFetchMock.mockImplementation(({ path }) => {
      if (path.includes('surecart/v1/fulfillments')) return Promise.resolve([]);
      return Promise.reject(new Error('Not found'));
    });
    const consoleError = jest.spyOn(console, 'error').mockImplementation(() => {});
    const page = await renderPage();
    expect(page.root.style.display).toBe('none');
    consoleError.mockRestore();
  });
});
